  "learn_revela_present":{"name":"Presentar como un profesional","summary":"Una cabina de vuelo: vista del moderador, notas, mando con el móvil, puntero láser y tinta, pizarra, cuenta atrás y atajos","cat":"showcase","file":"learn_revela"},
  "learn_revela_live":{"name":"Votaciones y actividades en directo","summary":"Un plató de concurso: votación, nube de palabras, cuestionario con puntos, cuenta atrás, clasificación y actividad de ordenar, de verdad","cat":"showcase","file":"learn_revela"},
  "learn_revela_collab":{"name":"Colaborar y compartir","summary":"Un tablón de corcho: colaborar a la vez, permisos al compartir, comentarios y tareas reales, enlaces, versiones y una actividad de unir","cat":"showcase","file":"learn_revela"},
  "learn_revela_ai":{"name":"La IA de Revela","summary":"Un chat bajo la aurora: crear una presentación, reescribir textos (con Transformar por palabras), imágenes, el asistente y más ayudas","cat":"showcase","file":"learn_revela"},
  "learn_revela_design":{"name":"Diseño: patrón, temas y colores","summary":"Un muestrario: patrón y diseños de diapositiva, temas, paletas y fuentes, contraste calculado, Text Art, texto curvo e ideas de diseño","cat":"showcase","file":"learn_revela"},
  "learn_revela_export":{"name":"Exportar y llevártelo","summary":"Un panel de salidas: PDF, PowerPoint, vídeo, página web, SCORM, imprimir con notas y atajos de teclado, con votación final","cat":"showcase","file":"learn_revela"},
