  "life_food_paella":{"name":"Paella valenciana","summary":"Paellera de formas sobre llamas, ingredientes en cadena, cantidades con fórmulas, cronología, corte del socarrat con Text Art, cuenta atrás y votación","cat":"life","file":"life_food"},
