  "life_food_bbq":{"name":"Brasa y parrilla","summary":"Brasero 3D que se mueve con Transformar, Text Art fuego, parrilla de dos zonas, tabla, barras de temperatura, ecuación, cuenta atrás y concurso","cat":"life","file":"life_food"},
  "life_travel_eu_lisbon":{"name":"Lisboa: colinas y tranvías","summary":"Azulejos en SVG, tranvía que sube las colinas por un recorrido con sonido, perfil de altura, cartas que giran, tabla con fórmulas y huecos","cat":"life","file":"life_travel_eu"},
